import { defineConfig } from 'orval'

// Generates typed TanStack Query hooks from the API contract snapshot (openapi.json, kept in
// step with the API by OpenApiSnapshotTests). Never edit src/api/generated by hand.
export default defineConfig({
  hishab: {
    input: { target: './openapi.json' },
    output: {
      target: './src/api/generated/hishab.ts',
      mode: 'single',
      client: 'react-query',
      httpClient: 'fetch',
      clean: true,
      override: {
        mutator: { path: './src/api/http.ts', name: 'apiFetch' },
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
})
